/* BankAuctions.ai · site-visit capture form, shared by the website field console and the Android app */
(function(){
var FV=window.FV,BA=window.BA,esc=BA.esc,jg=BA.jget;
var SAMPLES=[];BA.allRaw().forEach(function(p){(p.fvimgs||[]).forEach(function(n){if(SAMPLES.indexOf(n)<0)SAMPLES.push(n)})});
function sz(b){b=+b||0;return b>1048576?(b/1048576).toFixed(1)+' MB':Math.max(1,Math.round(b/1024))+' KB'}
function bad(m){BA.toast(m)}
FV.form=function(root,id,o){o=o||{};var p=FV.property(id),timer=null,saved=0;
 function A(){return FV.asg()[id]}
 function ro(){return !!o.readonly||!A()||!!A().sub||A().fin==='approved'}
 function save(d){FV.saveDraft(id,d);saved=Date.now();var el=root.querySelector('.fvsv');if(el)el.textContent='Draft saved '+new Date(saved).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}
 function later(d){clearTimeout(timer);timer=setTimeout(function(){save(d)},350)}
 function sec(k,t,cnt,inner,hint){return '<section class="fvs" data-sec="'+k+'"><div class="fvh"><b>'+t+'</b>'+(cnt?'<span class="fvc">'+cnt+'</span>':'')+'</div>'+(hint?'<p class="fvp">'+hint+'</p>':'')+inner+'</section>'}
 function file(kind,acc,label,multi,cls){return '<label class="fbn '+(cls||'')+'">'+label+'<input type="file" hidden accept="'+acc+'"'+(multi?' multiple':'')+' data-up="'+kind+'"></label>'}
 function sel(f,label,opts,d){return '<label class="fl">'+label+'<select class="fin" data-f="'+f+'"><option value="">Select</option>'+opts.map(function(x){return '<option'+(d[f]===x?' selected':'')+'>'+x+'</option>'}).join('')+'</select></label>'}
 function foot(d,dis){var need=FV.need(d),miss=need.filter(function(x){return !x.ok}).length;
  return '<section class="fvs fvft"><div class="fvh"><b>Ready to submit?</b><span class="fvc '+(miss?'':'g')+'">'+(miss?miss+' to go':'All set')+'</span></div><ul class="fvck2">'+need.map(function(x){return '<li class="'+(x.ok?'y':'')+'">'+x.label+(x.now&&!x.ok?' <small>('+x.now+')</small>':'')+'</li>'}).join('')+'</ul>'+(dis?'':'<div class="fvr"><button class="fbn s" data-save="1">Save draft</button><button class="fbn" data-submit="1"'+(miss?' disabled':'')+'>Submit to checker</button></div><p class="fvp fvsv">'+(d.upd?'Draft saved '+new Date(d.upd).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'Nothing saved yet')+'</p><p class="fvp">You can leave and come back. Your draft stays on this device until you submit.</p>')+'</section>';}
 function refreshFoot(){var el=root.querySelector('.fvft');if(el){var d=FV.draft(id);el.outerHTML=foot(d,ro())}}
 function render(){var d=FV.draft(id),a=A(),dis=ro(),sp=root.closest('#view')||document.scrollingElement||document.documentElement,sc=sp.scrollTop,need=FV.need(d),miss=need.filter(function(x){return !x.ok}).length;
  var h='';
  if(a&&a.ret)h+='<div class="fvn"><b>Returned by '+esc(a.ret.by)+'</b><br>'+esc(a.ret.note)+'</div>';
  if(dis&&a&&a.sub&&a.fin!=='approved')h+='<div class="fvn ok"><b>Submitted to the checker.</b> You will be told if they return it with comments. It cannot be edited while it is being checked.</div>';
  if(a&&a.fin==='approved')h+='<div class="fvn ok"><b>Approved and published</b> on the property page.</div>';
  h+=sec('photos','Site photographs',d.photos.length+' of 8','<div class="fvph">'+d.photos.map(function(x,i){return '<div class="fvt">'+BA.im(x.k,'width:100%;height:100%;object-fit:cover')+(dis?'':'<button class="fvx" data-rm="photos:'+i+'" aria-label="Remove photo">✕</button>')+'</div>'}).join('')+'</div>'+(dis?'':'<div class="fvr">'+(d.photos.length<8?file('photos','image/*','📷 Take or add photos',true):'')+(d.photos.length<8?'<button class="fbn s" data-demo="photos">Add sample photos (demo)</button>':'<span class="fvp">Maximum of 8 photographs reached.</span>')+'</div>'),'Latest photographs of the property: outside, inside, boundaries and the approach road. At least 3 and up to 8.');
  h+=sec('video','Video tour',d.video?'1 video':'','<div>'+(d.video?'<video controls playsinline preload="metadata" '+(d.video.k.indexOf('idb:')===0?'data-idb="'+esc(d.video.k)+'"':'src="'+esc(d.video.k)+'"')+' class="fvv"></video><p class="fvp">'+esc(d.video.n)+(d.video.size?' · '+sz(d.video.size):'')+'</p>'+(dis?'':'<button class="fbn s" data-rm="video:0">Remove video</button>'):'')+'</div>'+(dis||d.video?'':'<div class="fvr">'+file('video','video/*','🎥 Record or add a video',false)+'<button class="fbn s" data-demo="video">Add sample video (demo)</button></div>'),'Walk through the property and its surroundings. One video, up to 80 MB.');
  h+=sec('deed','Sale deed',d.deed.length?d.deed.length+' file'+(d.deed.length>1?'s':''):'','<div class="fvl">'+d.deed.map(function(x,i){return '<div class="fvf"><span><b>'+esc(x.n)+'</b><br><small>'+(x.t==='application/pdf'?'PDF':'Picture')+(x.size?' · '+sz(x.size):'')+'</small></span>'+(dis?'':'<button class="fvx2" data-rm="deed:'+i+'" aria-label="Remove">✕</button>')+'</div>'}).join('')+'</div>'+(dis?'':'<div class="fvr">'+file('deed','image/*,application/pdf','📄 Scan or add sale deed pages',true)+'<button class="fbn s" data-demo="deed">Add sample page (demo)</button></div>'),'Scanned copy or photographs of the sale deed. Add every page.');
  h+=sec('ec','Latest encumbrance certificate (EC)',(d.ec||[]).length?(d.ec||[]).length+' file'+((d.ec||[]).length>1?'s':''):'','<div class="fvl">'+(d.ec||[]).map(function(x,i){return '<div class="fvf"><span><b>'+esc(x.n)+'</b><br><small>'+(x.t==='application/pdf'?'PDF':'Picture')+(x.size?' · '+sz(x.size):'')+'</small></span>'+(dis?'':'<button class="fvx2" data-rm="ec:'+i+'" aria-label="Remove">✕</button>')+'</div>'}).join('')+'</div>'+(dis?'':'<div class="fvr">'+file('ec','image/*,application/pdf','📄 Scan or add the latest EC',true)+'<button class="fbn s" data-demo="ec">Add sample page (demo)</button></div>'),'Collect the latest encumbrance certificate from the bank manager or their representative. Add every page.');
  h+=sec('docs','Other documents from the bank',d.docs.length?d.docs.length+' added':'','<div class="fvl">'+d.docs.map(function(x,i){return '<div class="fvf"><span><b>'+esc(x.title)+'</b><br><small>'+esc(x.n)+(x.size?' · '+sz(x.size):'')+'</small></span>'+(dis?'':'<button class="fvx2" data-rm="docs:'+i+'" aria-label="Remove">✕</button>')+'</div>'}).join('')+'</div>'+(dis?'':'<div class="fvg2"><label class="fl">Document name<input class="fin" id="fdn" placeholder="e.g. Encumbrance certificate, possession notice"></label><label class="fl">File<input class="fin" id="fdf" type="file" accept="image/*,application/pdf"></label></div><button class="fbn s" data-adddoc="1">+ Add this document</button>'),'Every other document the bank gave you. Give each one a name so the checker knows what it is. Add as many as you were given.');
  var g=d.gps||{};
  h+=sec('loc','Location',g.lat!=null&&g.lng!=null&&g.lat!==''?'GPS set':'','<div class="fvr">'+(dis?'':'<button class="fbn" data-gps="1">📍 Use my current location</button>')+'</div><div class="fvg2"><label class="fl">Latitude<input class="fin" inputmode="decimal" data-f="gps.lat" value="'+esc(g.lat==null?'':g.lat)+'" placeholder="13.0827"'+(dis?' disabled':'')+'></label><label class="fl">Longitude<input class="fin" inputmode="decimal" data-f="gps.lng" value="'+esc(g.lng==null?'':g.lng)+'" placeholder="80.2707"'+(dis?' disabled':'')+'></label></div><label class="fl">Google Maps link<input class="fin" data-f="maps" value="'+esc(d.maps||'')+'" placeholder="https://www.google.com/maps?q=13.0827,80.2707"'+(dis?' disabled':'')+'></label>'+(d.maps?'<p class="fvp"><a href="'+esc(d.maps)+'" target="_blank" rel="noopener">Open in Google Maps ↗</a>'+(g.acc?' · GPS accuracy about '+Math.round(g.acc)+' m':'')+'</p>':''),'Stand at the property gate when you capture this. The map link is filled in for you from the GPS reading.');
  h+=sec('lm','Prominent landmarks',d.landmarks.filter(function(x){return x.name&&+x.km>0}).length+' added','<div>'+d.landmarks.map(function(x,i){return '<div class="fvlm"><input class="fin" data-lm="'+i+':name" value="'+esc(x.name)+'" placeholder="Landmark, e.g. Tidel Park"'+(dis?' disabled':'')+'><input class="fin km" inputmode="decimal" data-lm="'+i+':km" value="'+esc(x.km)+'" placeholder="km"'+(dis?' disabled':'')+'>'+(dis?'':'<button class="fvx2" data-rm="landmarks:'+i+'" aria-label="Remove">✕</button>')+'</div>'}).join('')+'</div>'+(dis?'':'<button class="fbn s" data-addlm="1">+ Add a landmark</button>'),'Well-known places near the property and the distance in kilometres.');
  var PR=['Corner plot','Major intersection','Beside a major landmark','Good rental yield','Good resale value'],BD=['Railway line','Dumping yard','Burial ground','Marriage hall','Temple or mosque','Drain or sewage canal','High-tension line'];
  h+=sec('pn','Positives and negatives','','<label class="fl">Positives (one per line)<textarea class="fin" rows="3" data-f="pos" placeholder="e.g. Wide road, close to metro"'+(dis?' disabled':'')+'>'+esc(d.pos||'')+'</textarea></label><label class="fl">Negatives (one per line, or write None seen)<textarea class="fin" rows="3" data-f="neg" placeholder="e.g. Tenant in possession"'+(dis?' disabled':'')+'>'+esc(d.neg||'')+'</textarea></label>','What a bidder should know before bidding, good and bad.');
  h+=sec('pm','Premium property check',(d.prem||[]).length?(d.prem||[]).length+' reasons':'','<p class="fvp">Tick every reason this property deserves to be listed as a premium property. The checker decides.</p><div class="fvck">'+PR.map(function(u){return '<label><input type="checkbox" data-pr="'+u+'"'+((d.prem||[]).indexOf(u)>-1?' checked':'')+(dis?' disabled':'')+'> '+u+'</label>'}).join('')+'</div><label class="fl">Anything else that makes it special<input class="fin" data-f="premNote" value="'+esc(d.premNote||'')+'"'+(dis?' disabled':'')+'></label><p class="fvp">Is it near any of these? Tick if yes. Such properties are not listed as premium.</p><div class="fvck">'+BD.map(function(u){return '<label><input type="checkbox" data-nb="'+u+'"'+((d.nearBad||[]).indexOf(u)>-1?' checked':'')+(dis?' disabled':'')+'> '+u+'</label>'}).join('')+'</div>','Optional. Helps the checker decide whether to list the property in the Premium section.');
  h+=sec('val','Valuation','','<p class="fvp">Bank reserve price: <b>'+BA.inr(p.reserve)+'</b> · listed '+p.disc+'% below market</p><div class="fvg2"><label class="fl">Market value (₹ lakh)<input class="fin" inputmode="decimal" data-f="mv" value="'+esc(d.mv)+'" placeholder="e.g. 78"'+(dis?' disabled':'')+'></label><label class="fl">Recommended fair price (₹ lakh)<input class="fin" inputmode="decimal" data-f="fair" value="'+esc(d.fair)+'" placeholder="e.g. 62"'+(dis?' disabled':'')+'></label></div><p class="fvp" id="fvvh"></p>','What the property would sell for in an open market, and what a buyer should pay at auction.');
  h+=sec('obs','What you saw on site','','<div class="fvg2">'+sel('occ','Occupancy',['Vacant','Occupied by owner','Occupied by tenant','Unauthorised occupant'],d)+sel('access','Access road',['Wide, paved','Narrow, paved','Unpaved','No direct access'],d)+sel('boundary','Boundaries match documents',['Yes','Partly','No'],d)+sel('cond','Structure condition (1 poor, 5 good)',['1','2','3','4','5'],d)+'</div><div class="fvck">'+['Electricity','Water','Drainage','Gas'].map(function(u){return '<label><input type="checkbox" data-u="'+u+'"'+(d.util.indexOf(u)>-1?' checked':'')+(dis?' disabled':'')+'> '+u+' connected</label>'}).join('')+'</div><label class="fl">Litigation or notices seen on site<input class="fin" data-f="lit" value="'+esc(d.lit)+'" placeholder="None seen"'+(dis?' disabled':'')+'></label><label class="fl">Notes for customers<textarea class="fin" rows="3" data-f="notes" placeholder="What a buyer should know after standing there"'+(dis?' disabled':'')+'>'+esc(d.notes)+'</textarea></label>');
  h+=foot(d,dis);
  root.innerHTML=h;sp.scrollTop=sc;BA.hydrate(root);hint()}
 function hint(){var d=FV.draft(id),el=root.querySelector('#fvvh');if(!el)return;var mv=+d.mv,fp=+d.fair;el.textContent=mv>0&&fp>0?(fp>mv?'Your fair price is above the market value. Check both numbers.':'Fair price is '+Math.round((1-fp/mv)*100)+'% below your market value and '+(fp>=p.reserve?Math.round((fp/p.reserve-1)*100)+'% above':Math.round((1-fp/p.reserve)*100)+'% below')+' the bank reserve price.'):''}
 function setPath(d,path,v){var parts=path.split('.');var t=d;for(var i=0;i<parts.length-1;i++){t[parts[i]]=t[parts[i]]||{};t=t[parts[i]]}t[parts[parts.length-1]]=v}
 root.oninput=function(e){var t=e.target,d=FV.draft(id);if(t.dataset.f){setPath(d,t.dataset.f,t.value);if(/^gps\./.test(t.dataset.f)&&d.gps&&d.gps.lat!==''&&d.gps.lng!==''&&(!d.maps||d.mapsAuto)){d.maps='https://www.google.com/maps?q='+d.gps.lat+','+d.gps.lng;d.mapsAuto=true;var mi=root.querySelector('[data-f="maps"]');if(mi)mi.value=d.maps}if(t.dataset.f==='maps')d.mapsAuto=false;save(d);hint();refreshFoot()}
  else if(t.dataset.lm){var q=t.dataset.lm.split(':');d.landmarks[+q[0]][q[1]]=t.value;save(d);refreshFoot()}};
 root.onchange=function(e){var t=e.target,d=FV.draft(id);if(t.dataset.f&&t.tagName==='SELECT'){setPath(d,t.dataset.f,t.value);save(d);render();return}
  if(t.dataset.pr||t.dataset.nb){var k=t.dataset.pr?'prem':'nearBad',v=t.dataset.pr||t.dataset.nb;d[k]=d[k]||[];var j=d[k].indexOf(v);if(t.checked&&j<0)d[k].push(v);if(!t.checked&&j>-1)d[k].splice(j,1);save(d);return}
  if(t.dataset.u){var i=d.util.indexOf(t.dataset.u);if(t.checked&&i<0)d.util.push(t.dataset.u);if(!t.checked&&i>-1)d.util.splice(i,1);save(d);return}
  if(t.dataset.up){add(t.dataset.up,[].slice.call(t.files));t.value=''}};
 function put(blob){return BA.idb.put(blob)}
 function add(kind,files){if(!files.length)return;var d=FV.draft(id),busy=root.querySelector('[data-sec="'+kind+'"] .fvh');if(busy)busy.insertAdjacentHTML('beforeend','<span class="fvc">Saving…</span>');
  var chain=Promise.resolve();files.forEach(function(f){chain=chain.then(function(){
   if(kind==='photos'){if(d.photos.length>=8){bad('Maximum of 8 photographs');return}if(!/^image\//.test(f.type)){bad(f.name+' is not a picture');return}return FV.imgBlob(f,1400).then(put).then(function(k){d.photos.push({k:k,n:f.name})})}
   if(kind==='video'){if(!/^video\//.test(f.type)){bad(f.name+' is not a video');return}if(f.size>80*1048576){bad('That video is over 80 MB. Record a shorter one.');return}return put(f).then(function(k){d.video={k:k,n:f.name,size:f.size}})}
   if(kind==='ec'){var img=/^image\//.test(f.type);if(!img&&f.type!=='application/pdf'){bad(f.name+': add a picture or a PDF');return}if(f.size>12*1048576){bad(f.name+' is over 12 MB');return}return (img?FV.imgBlob(f,1800):Promise.resolve(f)).then(put).then(function(k){d.ec=d.ec||[];d.ec.push({k:k,n:f.name,t:img?'image/jpeg':'application/pdf',size:f.size})})}
   if(kind==='deed'){var img=/^image\//.test(f.type);if(!img&&f.type!=='application/pdf'){bad(f.name+': add a picture or a PDF');return}if(f.size>12*1048576){bad(f.name+' is over 12 MB');return}return (img?FV.imgBlob(f,1800):Promise.resolve(f)).then(put).then(function(k){d.deed.push({k:k,n:f.name,t:img?'image/jpeg':'application/pdf',size:f.size})})}
  })});
  chain.then(function(){save(d);render()},function(err){bad((err&&err.message)||'Could not save that file on this device');render()})}
 root.onclick=function(e){var t=e.target.closest('button');if(!t)return;var d=FV.draft(id),ds=t.dataset;
  if(ds.rm){var q=ds.rm.split(':'),k=q[0],i=+q[1];if(k==='video'){var v=d.video;d.video=null;if(v&&v.k.indexOf('idb:')===0)BA.idb.del(v.k)}else{var x=d[k].splice(i,1)[0];if(x&&x.k&&x.k.indexOf('idb:')===0)BA.idb.del(x.k)}save(d);render();return}
  if(ds.addlm){d.landmarks.push({name:'',km:''});save(d);render();var ins=root.querySelectorAll('.fvlm input');if(ins.length)ins[ins.length-2].focus();return}
  if(ds.demo==='photos'){var have=d.photos.map(function(x){return x.k}),n=0;SAMPLES.forEach(function(s){if(d.photos.length<8&&n<4&&have.indexOf(s)<0){d.photos.push({k:s,n:'Sample photo'});n++}});save(d);render();return}
  if(ds.demo==='video'){d.video={k:'img/demo-tour.mp4',n:'Sample site walkthrough.mp4',size:0};save(d);render();return}
  if(ds.demo==='ec'){d.ec=d.ec||[];d.ec.push({k:'demo-deed.jpg',n:'Sample EC page '+(d.ec.length+1),t:'image/jpeg',size:0});save(d);render();return}
  if(ds.demo==='deed'){d.deed.push({k:'demo-deed.jpg',n:'Sample sale deed page '+(d.deed.length+1),t:'image/jpeg',size:0});save(d);render();return}
  if(ds.adddoc){var nm=(root.querySelector('#fdn').value||'').trim(),fl=root.querySelector('#fdf').files[0];if(!nm){bad('Give the document a name first');return}if(!fl){bad('Choose the file for this document');return}if(fl.size>12*1048576){bad('That file is over 12 MB');return}var img=/^image\//.test(fl.type);if(!img&&fl.type!=='application/pdf'){bad('Add a picture or a PDF');return}
   (img?FV.imgBlob(fl,1800):Promise.resolve(fl)).then(put).then(function(k){d.docs.push({title:nm,k:k,n:fl.name,t:img?'image/jpeg':'application/pdf',size:fl.size});save(d);render()},function(err){bad((err&&err.message)||'Could not save that file')});return}
  if(ds.gps){if(!navigator.geolocation){bad('This device cannot give its location. Type the latitude and longitude.');return}t.disabled=true;t.textContent='Finding you…';
   navigator.geolocation.getCurrentPosition(function(r){d.gps={lat:+r.coords.latitude.toFixed(6),lng:+r.coords.longitude.toFixed(6),acc:r.coords.accuracy,at:Date.now()};d.maps='https://www.google.com/maps?q='+d.gps.lat+','+d.gps.lng;d.mapsAuto=true;save(d);render();bad('Location captured')},function(){t.disabled=false;t.textContent='📍 Use my current location';bad('Could not read your location. Allow location access or type the latitude and longitude.')},{enableHighAccuracy:true,timeout:15000});return}
  if(ds.save){save(d);bad('Draft saved. You can finish it later.');return}
  if(ds.submit){if(!FV.complete(d)){bad('Some items are still missing');return}d.landmarks=d.landmarks.filter(function(x){return x.name&&+x.km>0});save(d);if(FV.submit(id,o.eng)){bad('Submitted to the checker');render();if(o.onSubmit)o.onSubmit(id)}}};
 render();return {render:render}};
})();
